from fractions import Fraction as F
import json

# Breakpoints of f(x) = |x+23| + |x-5| + |x-48|
C = [F(-23), F(5), F(48)]

def f(x):
    return abs(x + 23) + abs(x - 5) + abs(x - 48)

def count_solutions(k):
    """Exact count of real x with f(x) = 2x + k.
    Returns None when the solution set is infinite."""
    sols = set()
    infinite = False

    # Breakpoints are checked directly.
    for c in C:
        if f(c) == 2 * c + k:
            sols.add(c)

    # Open pieces between breakpoints, including the unbounded ends.
    pts = sorted(C)
    bounds = [None] + pts + [None]
    for i in range(len(bounds) - 1):
        lo, hi = bounds[i], bounds[i + 1]
        if lo is None:
            p = hi - 1
        elif hi is None:
            p = lo + 1
        else:
            p = (lo + hi) / 2
        # On this piece |x-c| = s*(x-c) with s = sign(p-c), so f(x) = S*x - T.
        S = 0
        T = F(0)
        for c in C:
            s = 1 if p > c else -1
            S += s
            T += s * c
        # Equation S*x - T = 2x + k  ->  (S-2)*x = k + T
        a = S - 2
        b = F(k) + T
        if a == 0:
            if b == 0:
                infinite = True
            continue
        x = b / a
        inside = (lo is None or x > lo) and (hi is None or x < hi)
        if inside:
            sols.add(x)

    if infinite:
        return None
    return len(sols)

# Only k values where the root count can change matter: the critical values h(c) = f(c) - 2c.
candidates = sorted({f(c) - 2 * c for c in C})

counts = {}
valid = []
for k in candidates:
    n = count_solutions(k)
    counts[str(k)] = "infinite" if n is None else n
    if n == 1:
        valid.append(k)

total = sum(valid, F(0))

result = {
    "final_answer": str(total),
    "evidence": {
        "candidate_k": [str(k) for k in candidates],
        "solution_counts": counts,
        "valid_k": [str(k) for k in valid],
    },
}
print(json.dumps(result, separators=(",", ":")))
